export function runThreeWayMatchV2027(state:WindowsCompletionStateV2027,mb:MultiBusinessEnterpriseStateV2023,poId:string,actor:string){const po=mb.purchase_orders.find(x=>x.id===poId);if(!po)throw new Error('purchase_order_not_found');const receipt=[...mb.goods_receipts].filter(x=>x.purchase_order_id===po.id).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];const invoice=[...mb.purchase_invoices].filter(x=>x.purchase_order_id===po.id).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];const ordered=round(po.lines.reduce((s,l)=>s+l.ordered_quantity_base,0),4),accepted=round(receipt?.lines.reduce((s,l)=>s+l.accepted_quantity_base,0)||0,4),pov=poValue(po),inv=round(invoice?.total_sar||0);const qv=round(accepted-ordered,4),vv=round(inv-pov);const qPct=ordered?Math.abs(qv)/ordered*100:0,vPct=pov?Math.abs(vv)/pov*100:0;const status:ThreeWayMatchV2027['status']=!receipt||!invoice?'blocked':qPct<=state.settings.three_way_quantity_tolerance_pct&&vPct<=state.settings.three_way_value_tolerance_pct?'matched':'variance';const row:ThreeWayMatchV2027={id:rid('TWM'),match_number:serial('TWM'),purchase_order_id:po.id,goods_receipt_id:receipt?.id,purchase_invoice_id:invoice?.id,ordered_qty:ordered,accepted_qty:accepted,po_value_sar:pov,invoice_value_sar:inv,quantity_variance:qv,value_variance_sar:vv,status,checked_by:actor,checked_at:now()};return audit({...state,three_way_matches:[row,...state.three_way_matches]},actor,'procurement.three_way_match','purchase_order',po.id,undefined,row);}
