export function solveLeastCostFormulaV2027(state:WindowsCompletionStateV2027,mb:MultiBusinessEnterpriseStateV2023,input:{factory_id:string;target_output_kg:number;target_protein_pct:number;target_energy_kcal_kg:number;target_calcium_pct:number;candidates:LeastCostCandidateV2027[];generated_by:string}){
  if(input.target_output_kg<=0||input.candidates.length<2)throw new Error('least_cost_candidates_required');const mats=input.candidates.map(c=>({c,m:mb.raw_material_definitions.find(x=>x.id===c.raw_material_definition_id)}));if(mats.some(x=>!x.m))throw new Error('raw_material_definition_not_found');let pct=input.candidates.map(c=>Math.max(c.min_pct,Math.min(c.max_pct,100/input.candidates.length)));const normalize=()=>{let sum=pct.reduce((s,x)=>s+x,0);if(!sum)return; pct=pct.map(x=>x/sum*100);};normalize();let best:{score:number;pct:number[]}|undefined;const calc=(p:number[])=>{let protein=0,energy=0,calcium=0,cost=0;for(let i=0;i<p.length;i++){const f=p[i]/100,m=mats[i].m as any;protein+=f*nutrient(m,'protein_pct');energy+=f*nutrient(m,'metabolizable_energy_kcal_kg');calcium+=f*nutrient(m,'calcium_pct');cost+=f*input.candidates[i].cost_per_kg_sar;}const penalty=Math.abs(protein-input.target_protein_pct)*100+Math.abs(energy-input.target_energy_kcal_kg)*0.05+Math.abs(calcium-input.target_calcium_pct)*300;return {protein,energy,calcium,cost,score:cost+penalty};};
  for(let it=0;it<1200;it++){const current=calc(pct);if(!best||current.score<best.score)best={score:current.score,pct:[...pct]};const i=it%pct.length,j=(it*7+3)%pct.length;if(i===j)continue;const step=it<300?2:it<700?0.5:0.1;const trial=[...pct];if(trial[i]+step<=input.candidates[i].max_pct&&trial[j]-step>=input.candidates[j].min_pct){trial[i]+=step;trial[j]-=step;if(calc(trial).score<current.score)pct=trial;}if(it%41===0)normalize();}
  pct=best?.pct||pct;const final=calc(pct);const feasible=Math.abs(final.protein-input.target_protein_pct)<=1&&Math.abs(final.energy-input.target_energy_kcal_kg)<=100&&Math.abs(final.calcium-input.target_calcium_pct)<=0.2;const row:LeastCostResultV2027={id:rid('LCF'),factory_id:input.factory_id,target_output_kg:input.target_output_kg,target_protein_pct:input.target_protein_pct,target_energy_kcal_kg:input.target_energy_kcal_kg,target_calcium_pct:input.target_calcium_pct,ingredients:pct.map((p,i)=>({raw_material_definition_id:input.candidates[i].raw_material_definition_id,product_id:input.candidates[i].product_id,percentage:round(p,4),quantity_kg:round(input.target_output_kg*p/100,4),cost_sar:round(input.target_output_kg*p/100*input.candidates[i].cost_per_kg_sar)})),calculated:{protein_pct:round(final.protein,4),energy_kcal_kg:round(final.energy,2),calcium_pct:round(final.calcium,4)},total_cost_sar:round(final.cost*input.target_output_kg),cost_per_kg_sar:round(final.cost,4),feasible,iterations:1200,generated_by:input.generated_by,generated_at:now()};return {state:audit({...state,least_cost_results:[row,...state.least_cost_results]},input.generated_by,'factory.least_cost_solve','factory',input.factory_id,undefined,row),result:row};}
export function createProductionPlanV2027(state:WindowsCompletionStateV2027,feed:FeedFactoryOperationsStateV2024,mb:MultiBusinessEnterpriseStateV2023,input:{factory_id:string;period_from:string;period_to:string;demand_kg:number;safety_stock_kg:number;finished_product_id:string;planned_formula_id?:string;created_by:string}){const factory=mb.factories.find(x=>x.id===input.factory_id);if(!factory?.finished_goods_warehouse_id)throw new Error('factory_finished_goods_warehouse_required');const stock=inventoryBalanceV2023(mb,factory.finished_goods_warehouse_id,input.finished_product_id);const recommended=Math.max(0,round(input.demand_kg+input.safety_stock_kg-stock,3));if(input.planned_formula_id&&!feed.formulas.some(x=>x.id===input.planned_formula_id&&x.status==='approved'))throw new Error('approved_formula_required');const row:ProductionPlanV2027={id:rid('PPLAN'),plan_number:serial('PPLAN'),factory_id:input.factory_id,period_from:input.period_from,period_to:input.period_to,demand_kg:input.demand_kg,finished_stock_kg:stock,safety_stock_kg:input.safety_stock_kg,recommended_production_kg:recommended,planned_formula_id:input.planned_formula_id,status:'draft',created_by:input.created_by,created_at:now()};return audit({...state,production_plans:[row,...state.production_plans]},input.created_by,'factory.production_plan','factory',input.factory_id,undefined,row);}

export function renewBusinessContractV2027(state:WindowsCompletionStateV2027,mb:MultiBusinessEnterpriseStateV2023,contractId:string,input:{start_date:string;end_date?:string;approved_by:string;patch?:Partial<Pick<BusinessContractV2023,'services'|'payment_terms'|'platform_commission_percent'|'approval_limit_sar'|'expense_rules'>>}){const old=mb.contracts.find(x=>x.id===contractId);if(!old)throw new Error('business_contract_not_found');if(new Date(input.end_date||input.start_date)<new Date(input.start_date))throw new Error('business_contract_invalid_range');const nextContract:BusinessContractV2023={...old,...(input.patch||{}),id:rid('BCTR'),contract_number:serial('BCTR'),start_date:input.start_date,end_date:input.end_date,status:'active',created_at:now()};const changed=Object.keys(input.patch||{});if(old.start_date!==input.start_date)changed.push('start_date');if(old.end_date!==input.end_date)changed.push('end_date');const previous={...old,status:'expired' as const};const nextMb={...mb,contracts:[nextContract,...mb.contracts.map(x=>x.id===old.id?previous:x).filter(x=>x.id!==nextContract.id)],business_units:mb.business_units.map(x=>x.id===old.business_unit_id?{...x,contract_id:nextContract.id}:x),farm_links:mb.farm_links.map(x=>x.contract_id===old.id&&x.active?{...x,contract_id:nextContract.id}:x)};const renewal:BusinessContractRenewalV2027={id:rid('BCRN'),business_unit_id:old.business_unit_id,previous_contract_id:old.id,new_contract_id:nextContract.id,effective_from:input.start_date,changed_fields:[...new Set(changed)],approved_by:input.approved_by,created_at:now()};return {state:audit({...state,business_contract_renewals:[renewal,...state.business_contract_renewals]},input.approved_by,'business_contract.renew','business_contract',old.id,old,nextContract),multiBusiness:nextMb,contract:nextContract,renewal};}

export function renewCompensationContractV2027(state:WindowsCompletionStateV2027,workforce:WorkforcePayrollStateV2025,contractId:string,input:{start_date:string;end_date?:string;approved_by:string;patch?:Partial<Pick<CompensationContractV2025,'base_salary'|'daily_rate'|'hourly_rate'|'overtime_rate'|'per_visit_fee'|'per_farm_fee'|'per_cycle_fee'|'transport_allowance'|'housing_allowance'|'other_allowance'|'payer_breakdown'|'payment_day'>>}){const old=workforce.compensation_contracts.find(x=>x.id===contractId);if(!old)throw new Error('compensation_contract_not_found');const newContract:CompensationContractV2025={...old,...(input.patch||{}),id:rid('WCON'),contract_number:serial('WCON'),start_date:input.start_date,end_date:input.end_date,status:'active',created_by:input.approved_by,created_at:now()};const nextWork={...workforce,compensation_contracts:[newContract,...workforce.compensation_contracts.map(x=>x.id===old.id?{...x,status:'expired' as const}:x)]};const changed=Object.keys(input.patch||{});const row:ContractRenewalV2027={id:rid('CREN'),employee_id:old.employee_id,previous_contract_id:old.id,new_contract_id:newContract.id,effective_from:input.start_date,changed_fields:changed,approved_by:input.approved_by,created_at:now()};return {state:audit({...state,contract_renewals:[row,...state.contract_renewals]},input.approved_by,'hr.contract_renew','employee',old.employee_id,old,newContract),workforce:nextWork,contract:newContract};}
export function generatePayslipV2027(state:WindowsCompletionStateV2027,workforce:WorkforcePayrollStateV2025,payrollLineId:string,actor:string){const line=workforce.payroll_lines.find(x=>x.id===payrollLineId);if(!line)throw new Error('payroll_line_not_found');const emp=workforce.profiles.find(x=>x.employee_id===line.employee_id);const period=workforce.payroll_periods.find(x=>x.id===line.payroll_period_id);const row:PayslipSnapshotV2027={id:rid('PAYSLIP'),payslip_number:serial('PS'),employee_id:line.employee_id,payroll_line_id:line.id,period_id:line.payroll_period_id,generated_at:now(),generated_by:actor,data:{employee_number:emp?.employee_number,employee_name:emp?.full_name,period:period?.period_code,currency:line.currency,base_pay:line.base_pay,allowances:line.allowances,overtime_pay:line.overtime_pay,visit_pay:line.visit_pay,commission:line.commission,bonus:line.bonus,gross_pay:line.gross_pay,advance_recovery:line.advance_recovery,other_deductions:line.other_deductions,net_pay:line.net_pay,net_pay_sar:line.net_pay_sar,paid_sar:line.paid_sar,balance_sar:line.balance_sar,status:line.status}};return audit({...state,payslips:[row,...state.payslips]},actor,'hr.payslip_generate','payroll_line',line.id,undefined,row);}

export function indexEvidenceDocumentV2027(state:WindowsCompletionStateV2027,foundation:EnterpriseFoundationStateV2021,evidenceId:string,actor:string){const doc=foundation.evidence_documents.find(x=>x.id===evidenceId);if(!doc)throw new Error('evidence_document_not_found');const row:UnifiedDocumentIndexV2027={id:rid('DOCIDX'),evidence_document_id:doc.id,entity_type:doc.entity_type,entity_id:doc.entity_id,classification:doc.classification,retention_until:doc.retention_until,immutable:doc.immutable,indexed_at:now()};return audit({...state,document_index:[row,...state.document_index.filter(x=>x.evidence_document_id!==doc.id)]},actor,'document.index','evidence_document',doc.id,undefined,row);}
export function queueNotificationDeliveryV2027(state:WindowsCompletionStateV2027,notification:EnterpriseNotificationV2021,input:{channel:NotificationDeliveryV2027['channel'];recipient:string},actor:string){const row:NotificationDeliveryV2027={id:rid('NDEL'),notification_id:notification.id,channel:input.channel,recipient:input.recipient,status:'queued',attempts:0};return audit({...state,notification_deliveries:[row,...state.notification_deliveries]},actor,'notification.delivery_queue','notification',notification.id,undefined,row);}
export function markNotificationDeliveryV2027(state:WindowsCompletionStateV2027,id:string,input:{status:'sent'|'acknowledged'|'failed';error?:string},actor:string){const old=state.notification_deliveries.find(x=>x.id===id);if(!old)throw new Error('notification_delivery_not_found');const row={...old,status:input.status,attempts:old.attempts+1,last_attempt_at:now(),error:input.error,acknowledged_at:input.status==='acknowledged'?now():old.acknowledged_at};return audit({...state,notification_deliveries:state.notification_deliveries.map(x=>x.id===id?row:x)},actor,'notification.delivery_update','notification_delivery',id,old,row);}
export function executeReportScheduleV2027(state:WindowsCompletionStateV2027,intel:ExecutiveIntelligenceStateV2026,scheduleId:string,actor:string){const s=intel.report_schedules.find(x=>x.id===scheduleId&&x.active);if(!s)throw new Error('active_report_schedule_not_found');const snap=intel.report_snapshots.find(x=>x.definition_code===s.definition_code&&(!s.business_unit_id||x.business_unit_id===s.business_unit_id));const row:ReportExecutionV2027={id:rid('REX'),schedule_id:s.id,definition_code:s.definition_code,business_unit_id:s.business_unit_id,format:s.format,status:snap?'generated':'queued',snapshot_id:snap?.id,recipients:s.recipients,generated_at:snap?now():undefined};return audit({...state,report_executions:[row,...state.report_executions]},actor,'report.schedule_execute','report_schedule',s.id,undefined,row);}
export function setLocalizationPreferenceV2027(state:WindowsCompletionStateV2027,userId:string,language:'ar'|'en',actor:string){const old=state.localization_preferences.find(x=>x.user_id===userId);const row:LocalizationPreferenceV2027={user_id:userId,language,direction:language==='ar'?'rtl':'ltr',updated_at:now()};return audit({...state,localization_preferences:[row,...state.localization_preferences.filter(x=>x.user_id!==userId)]},actor,'localization.preference','user',userId,old,row);}
export function enqueueOfflineCommandV2027(state:WindowsCompletionStateV2027,input:{idempotency_key:string;user_id:string;device_id:string;command_type:string;payload:Record<string,unknown>},actor:string){if(!input.idempotency_key&&state.settings.offline_idempotency_required)throw new Error('idempotency_key_required');const existing=state.offline_commands.find(x=>x.idempotency_key===input.idempotency_key);if(existing)return {state,command:existing,duplicate:true};const row:OfflineCommandV2027={id:rid('OFFQ'),...input,status:'queued',queued_at:now()};return {state:audit({...state,offline_commands:[row,...state.offline_commands]},actor,'offline.enqueue','offline_command',row.id,undefined,row),command:row,duplicate:false};}
export function completeOfflineCommandV2027(state:WindowsCompletionStateV2027,id:string,input:{result_ref?:string;error?:string;conflict?:boolean},actor:string){const old=state.offline_commands.find(x=>x.id===id);if(!old)throw new Error('offline_command_not_found');const row={...old,status:(input.conflict?'conflict':input.error?'failed':'completed') as OfflineCommandV2027['status'],completed_at:now(),result_ref:input.result_ref,error:input.error};return audit({...state,offline_commands:state.offline_commands.map(x=>x.id===id?row:x)},actor,'offline.complete','offline_command',id,old,row);}

export function veterinaryKpisV2027(foundation:EnterpriseFoundationStateV2021,vet:VeterinaryFieldStateV2022){const users=new Set<string>();foundation.veterinary_coverage.filter(x=>x.status==='active'||x.status==='scheduled').forEach(x=>users.add(x.vet_user_id));vet.medical_cases.forEach(x=>users.add(x.primary_vet_user_id));return [...users].map(user_id=>{const assignments=foundation.veterinary_coverage.filter(x=>x.vet_user_id===user_id&&(x.status==='active'||x.status==='scheduled'));const cases=vet.medical_cases.filter(x=>x.primary_vet_user_id===user_id);const open=cases.filter(x=>!['closed','resolved'].includes(x.status)).length;const critical=cases.filter(x=>x.severity==='critical'&&!['closed','resolved'].includes(x.status)).length;const consults=vet.consultations.filter(x=>x.assigned_consultant_user_id===user_id);const labReviewed=vet.lab_orders.filter(x=>x.reviewed_by_vet_user_id===user_id).length;const followups=vet.followups.filter(x=>x.assigned_vet_user_id===user_id);return {user_id,assignments:assignments.length,farms:new Set(assignments.flatMap(x=>x.farm_ids)).size,flocks:new Set(assignments.flatMap(x=>x.flock_ids)).size,cases_total:cases.length,cases_open:open,cases_critical:critical,consultations:consults.length,lab_reviews:labReviewed,followups_completed:followups.filter(x=>x.status==='completed').length,followups_missed:followups.filter(x=>x.status==='missed').length};});}
export function workforceKpisV2027(workforce:WorkforcePayrollStateV2025,web:EnterpriseWebStateV202){return workforce.profiles.map(p=>{const attendance=workforce.attendance.filter(x=>x.employee_id===p.employee_id);const assignments=workforce.assignments.filter(x=>x.employee_id===p.employee_id&&x.active);const tasks=web.role_tasks.filter(x=>x.assigned_user_id===p.user_id);const payroll=workforce.payroll_lines.filter(x=>x.employee_id===p.employee_id);return {employee_id:p.employee_id,user_id:p.user_id,full_name:p.full_name,job_family:p.job_family,assignments:assignments.length,attendance_days:attendance.filter(x=>!['absent','leave','sick_leave'].includes(x.status)).length,absence_days:attendance.filter(x=>x.status==='absent').length,field_visits:attendance.filter(x=>x.status==='field_visit').length,overtime_hours:round(attendance.reduce((n,x)=>n+x.overtime_hours,0),2),tasks_total:tasks.length,tasks_completed:tasks.filter(x=>x.status==='completed').length,tasks_overdue:tasks.filter(x=>x.status==='overdue').length,payroll_outstanding_sar:round(payroll.reduce((n,x)=>n+x.balance_sar,0))};});}

export function windowsCompletionDashboardV2027(state:WindowsCompletionStateV2027){return {version:state.version,security:{active_device_sessions:state.device_sessions.filter(x=>!x.revoked_at&&x.expires_at>now()).length,verified_mfa:state.mfa_enrollments.filter(x=>x.verified&&!x.disabled_at).length},veterinary:{leave_coverages:state.vet_leave_coverage.length,medication_lot_dispenses:state.medication_dispenses.length},finance:{periods_closed:state.accounting_periods.filter(x=>x.status==='closed').length,bank_reconciliations:state.bank_reconciliations.length,flock_financial_events:state.flock_financial_events.length},procurement:{three_way_matches:state.three_way_matches.length,supplier_scorecards:state.supplier_scorecards.length,claims_open:state.procurement_claims.filter(x=>!['settled','rejected'].includes(x.status)).length},inventory:{cycle_counts:state.cycle_counts.length,quarantined_lots:state.quarantines.filter(x=>x.status==='quarantined').length},factory:{qc_records:state.factory_qc.length,least_cost_runs:state.least_cost_results.length,production_plans:state.production_plans.length},hr:{contract_renewals:state.contract_renewals.length,business_contract_renewals:state.business_contract_renewals.length,payslips:state.payslips.length},platform:{documents_indexed:state.document_index.length,notification_deliveries:state.notification_deliveries.length,report_executions:state.report_executions.length,offline_queue:state.offline_commands.filter(x=>['queued','processing'].includes(x.status)).length}};}

export function validateWindowsCompletionStateV2027(state:WindowsCompletionStateV2027,web?:EnterpriseWebStateV202,foundation?:EnterpriseFoundationStateV2021,vet?:VeterinaryFieldStateV2022,mb?:MultiBusinessEnterpriseStateV2023,feed?:FeedFactoryOperationsStateV2024,workforce?:WorkforcePayrollStateV2025,intel?:ExecutiveIntelligenceStateV2026){const issues:string[]=[];const uniq=(a:string[],label:string)=>{const s=new Set<string>();for(const x of a){if(s.has(x))issues.push(`${label}_duplicate:${x}`);s.add(x)}};uniq(state.accounting_periods.map(x=>`${x.business_unit_id||'global'}:${x.code}`),'accounting_period');uniq(state.offline_commands.map(x=>x.idempotency_key).filter(Boolean),'idempotency_key');uniq(state.three_way_matches.map(x=>x.match_number),'three_way_match');for(const p of state.accounting_periods)if(new Date(p.date_to)<new Date(p.date_from))issues.push(`accounting_period_invalid:${p.id}`);for(const q of state.cycle_counts)if(q.physical_quantity<0)issues.push(`cycle_count_negative:${q.id}`);for(const r of state.least_cost_results){const pct=round(r.ingredients.reduce((s,x)=>s+x.percentage,0),3);if(Math.abs(pct-100)>0.2)issues.push(`formula_percentage_not_100:${r.id}`);}if(web)for(const j of web.journal_entries.filter(x=>x.status==='posted')){const d=round(j.lines.reduce((s,l)=>s+l.debit_sar,0),2),c=round(j.lines.reduce((s,l)=>s+l.credit_sar,0),2);if(Math.abs(d-c)>0.01)issues.push(`unbalanced_journal:${j.id}`);}if(foundation)for(const c of state.vet_leave_coverage)if(!foundation.veterinary_coverage.some(x=>x.id===c.source_assignment_id))issues.push(`coverage_orphan_assignment:${c.id}`);if(vet)for(const d of state.medication_dispenses)if(!vet.medication_orders.some(x=>x.id===d.medication_order_id))issues.push(`dispense_orphan_medication:${d.id}`);if(mb){for(const d of state.medication_dispenses)if(!mb.inventory_movements.some(x=>x.id===d.inventory_movement_id))issues.push(`dispense_orphan_inventory_movement:${d.id}`);for(const c of state.cycle_counts.filter(x=>x.inventory_movement_id))if(!mb.inventory_movements.some(x=>x.id===c.inventory_movement_id))issues.push(`cycle_count_orphan_movement:${c.id}`);for(const r of state.business_contract_renewals)if(!mb.contracts.some(x=>x.id===r.new_contract_id))issues.push(`business_contract_renewal_orphan:${r.id}`);}if(feed)for(const q of state.factory_qc.filter(x=>x.subject_type==='production_batch'))if(!feed.production_batches.some(x=>x.id===q.subject_id))issues.push(`qc_orphan_batch:${q.id}`);if(workforce)for(const p of state.payslips)if(!workforce.payroll_lines.some(x=>x.id===p.payroll_line_id))issues.push(`payslip_orphan_payroll:${p.id}`);if(intel)for(const e of state.report_executions.filter(x=>x.schedule_id))if(!intel.report_schedules.some(x=>x.id===e.schedule_id))issues.push(`report_execution_orphan_schedule:${e.id}`);return issues;}
